package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaViDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("Bảo vệ khỏi mọi tác hại", "Nhân danh Allah, với tên của Ngài, không có gì trên trái đất hoặc trên trời có thể gây hại, và Ngài là Đấng Nghe thấy Tất cả, Đấng Biết tất cả.", "Ba lần mỗi sáng và tối.", "Ai nói ba lần sáng tối, sẽ không có gì làm hại người ấy."),
        "dua_raditu_billahi" to DuaText("Hài lòng với Allah là Chúa", "Tôi hài lòng với Allah là Chúa của tôi, với Hồi giáo là tôn giáo của tôi và với Muhammad ﷺ là Nhà tiên tri của tôi.", "Ba lần sáng và tối.", "Allah có quyền làm hài lòng Ngài trong Ngày Phán xét."),
        "dua_hasbiyallah" to DuaText("Hasbiyallah (Allah là đủ)", "Allah đủ cho tôi; không có thần nào ngoài Ngài. Nơi Ngài, tôi đặt niềm tin cậy của mình, và Ngài là Chúa tể của ngai quyền năng.", "Bảy lần sáng và tối.", "Một câu Kinh Qur'an; Allah đủ để chống lại những lo lắng của thế giới này và Đời sau."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("SubhanAllahi wa bihamdihi", "Vinh quang thay Allah và mọi lời khen ngợi đều thuộc về Ngài.", "Một trăm lần một ngày.", "Ai nói điều này một trăm lần một ngày thì tội lỗi của mình sẽ được tha thứ, dù chúng giống như bọt biển."),
        "dua_tahleel_100" to DuaText("La ilaha illallahu wahdahu", "Không ai có quyền được tôn thờ ngoại trừ Allah, một mình, không có đối tác. Ngài là quyền thống trị và Ngài là sự ca ngợi, và Ngài có quyền trên mọi sự.", "Đức hạnh lớn là nói điều đó một trăm lần một ngày.", "Phần thưởng là giải phóng mười nô lệ, viết một trăm việc tốt, xóa bỏ một trăm tội lỗi và bảo vệ khỏi Shaytan cho đến tối."),
        "dua_leaving_mosque" to DuaText("Rời khỏi nhà thờ Hồi giáo", "Ôi Allah, tôi cầu xin Ngài về sự hào phóng của Ngài.", "Khi bước ra khỏi thánh đường bằng chân trái.", "Yêu cầu tiền thưởng và sự cung cấp của Allah khi rời khỏi nhà thờ Hồi giáo."),
        "dua_after_adhan" to DuaText("Sau Adhan", "Ôi Allah, Chúa của lời kêu gọi hoàn hảo này và lời cầu nguyện sắp được thiết lập, hãy ban cho Muhammad ﷺ al-Wasilah và đức hạnh, đồng thời nâng anh ta lên Trạm Ca ngợi mà Ngài đã hứa với anh ta.", "Sau khi adhan hoàn thành.", "Bất cứ ai nói điều này sẽ nhận được sự cầu thay của Nhà tiên tri ﷺ vào Ngày Phán xét."),
        "dua_after_salah_istighfar" to DuaText("Sau Fard Salah", "Tôi cầu xin sự tha thứ của Allah (3 lần). Ôi Allah, Ngài là Salam và từ Ngài là sự bình an. Phước thay cho Ngài, Hỡi Người sở hữu sự uy nghi và danh dự.", "Ngay sau lễ Salam.", "Nhà tiên tri ﷺ đã đọc điều này sau mỗi lời cầu nguyện bắt buộc."),
        "dua_after_salah_help_dhikr" to DuaText("Giúp Tôi Nhớ Bạn", "Lạy Allah, xin giúp con nhớ đến Ngài, cảm ơn Ngài và tôn thờ Ngài một cách tốt nhất.", "Sau mỗi lời cầu nguyện - Nhà tiên tri ﷺ khuyên Mu'adh (RA) nên nói điều đó.", "Lời khuyên đặc biệt của Nhà tiên tri ﷺ - sự xuất sắc và kiên định trong việc thờ phượng."),
        "dua_sleep_tasbeeh" to DuaText("Tasbeeh-e-Fatimi trước khi ngủ", "Vinh quang thay Allah (33), mọi lời khen ngợi đều dành cho Allah (33), Allah là Đấng vĩ đại nhất (34).", "Trước khi ngủ - Nhà tiên tri ﷺ đã dạy điều đó cho Fatimah và Ali (RA).", "Nhà tiên tri ﷺ nói rằng điều đó tốt cho bạn hơn là một người hầu."),
        "dua_sleep_qina_adhab" to DuaText("Bảo vệ khỏi sự trừng phạt", "Ôi Allah, xin bảo vệ tôi khỏi sự trừng phạt của Ngài vào Ngày Ngài phục sinh các tôi tớ Ngài.", "Ba lần, tay phải đặt dưới má.", "Biến giấc ngủ thành lời nhắc nhở về cái chết và sự chuẩn bị cho Đời Sau."),
        "dua_bad_dream" to DuaText("Sau một giấc mơ tồi tệ", "Tôi cầu xin Allah che chở khỏi Shaytan, kẻ đáng nguyền rủa.", "Sau cơn ác mộng: nhổ nhẹ sang trái ba lần rồi quay sang bên kia.", "Giấc mơ xấu sẽ không làm hại bạn; đừng nói với ai về điều đó."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("Ya Hayyu Ya Qayyum", "Hỡi Đấng hằng sống, Hỡi Đấng duy trì tất cả! Bởi lòng thương xót của Ngài, con tìm kiếm sự giúp đỡ.", "Khi một vấn đề trở nên rất nặng nề.", "Bất cứ khi nào có điều gì khiến Nhà tiên tri ﷺ đau buồn, ông ấy sẽ nói điều này."),
        "dua_entering_market" to DuaText("Bước vào thị trường", "Không ai có quyền được tôn thờ ngoại trừ Allah, một mình, không có đối tác. Ngài là quyền thống trị và Ngài là sự khen ngợi. Ngài ban sự sống và gây ra cái chết, Ngài hằng sống và không bao giờ chết. Mọi điều tốt lành đều ở trong tay Ngài và Ngài có quyền trên mọi sự.", "Khi bước vào chợ.", "Hadith đề cập đến phần thưởng lớn cho nó (một triệu việc tốt)."),
        "dua_adam_forgiveness" to DuaText("Dua của nhà tiên tri Adam (AS)", "Lạy Chúa, chúng con đã phạm lỗi lầm, và nếu Chúa không tha thứ và thương xót chúng con, chắc chắn chúng con sẽ là những người thiệt thòi.", "Sự ăn năn của Adam và Hawwa (AS).", "Sự ăn năn đầu tiên của nhân loại - Allah đã chấp nhận nó."),
        "dua_abu_bakr" to DuaText("Dua dạy cho Abu Bakr (RA)", "Ôi Allah, tôi đã phạm sai lầm rất lớn và không ai tha thứ tội lỗi ngoại trừ Ngài, vì vậy hãy ban cho tôi sự tha thứ từ Ngài và thương xót tôi. Quả thật, Ngài là Đấng Tha thứ, Đấng Thương xót.", "Nhà tiên tri ﷺ đã dạy điều đó cho Abu Bakr as-Siddiq (RA) để nói trong lời cầu nguyện (sau tashahhud).", "Một Sunnah dua để kết thúc lời cầu nguyện."),
        "dua_astaghfirullah_atubu" to DuaText("Istighfar hàng ngày", "Tôi cầu xin sự tha thứ của Allah và tôi quay về với Ngài để ăn năn.", "Nhà tiên tri ﷺ tìm kiếm sự tha thứ hơn bảy mươi lần một ngày.", "Nhà tiên tri ﷺ nói: Tôi cầu xin sự tha thứ của Allah và ăn năn với Ngài hơn bảy mươi lần một ngày."),
        "dua_laylatul_qadr" to DuaText("Dua cho Laylat al-Qadr", "Ôi Allah, Ngài là Đấng Tha thứ nhất và Ngài thích tha thứ, vì vậy hãy tha thứ cho tôi.", "Đã dạy Aisha (RA) cho Laylat al-Qadr.", "Một bản dua đặc biệt cho những đêm cuối cùng của tháng Ramadan và Laylat al-Qadr."),
        "dua_family_coolness" to DuaText("Ánh Mắt Lạnh (Vợ Chồng & Con cái)", "Lạy Chúa, xin ban cho chúng con từ vợ chồng và con cháu của chúng con đôi mắt lạnh lùng, và biến chúng con trở thành những người lãnh đạo của những người công chính.", "Một bản dua trong Kinh Qur'an dành cho người phối ngẫu và con cái ngay chính.", "Vì sự bình yên ở nhà và con cái ngay chính."),
        "dua_righteous_children" to DuaText("Vì con cháu chính nghĩa", "Lạy Chúa, xin ban cho con dòng dõi thuần khiết. Quả thật, Ngài là Đấng nghe lời cầu xin.", "Dua của nhà tiên tri Zakariyya (AS).", "Một bản duran Kinh Qur'an dành cho những người đang tìm kiếm trẻ em."),
        "dua_ibrahim_prayer_family" to DuaText("Người thành lập cầu nguyện", "Lạy Chúa, xin biến con thành người thiết lập lời cầu nguyện và từ con cháu của con. Lạy Chúa, xin chấp nhận lời cầu xin của con. Lạy Chúa, xin tha thứ cho con, cha mẹ con và các tín hữu vào Ngày tài khoản được thiết lập.", "Dua của Tiên tri Ibrahim (AS) cho bản thân và con cháu của ông.", "Thường được đọc ở cuối lời cầu nguyện."),
        "dua_newlywed" to DuaText("Chúc mừng các cặp vợ chồng mới cưới", "Cầu xin Allah ban phước lành cho bạn, gửi phước lành cho bạn và đưa cả hai bạn đến với nhau trong điều tốt lành.", "Khi chúc mừng ai đó về cuộc hôn nhân của họ.", "Sunnah chúc mừng cho một cuộc hôn nhân."),
        "dua_before_eating" to DuaText("Trước khi ăn", "Nhân danh Allah. (Nếu quên :) Nhân danh Allah, lúc bắt đầu và lúc kết thúc.", "Trước khi ăn. Nếu bạn quên, hãy nói lại giữa chừng.", "Nói Bismillah ngăn Shaytan chia sẻ thức ăn."),
        "dua_after_eating" to DuaText("Sau khi ăn", "Mọi lời khen ngợi đều dành cho Allah, người đã cho tôi ăn thứ này và cung cấp nó cho tôi mà không cần bất kỳ sức mạnh hay quyền lực nào từ phía tôi.", "Sau khi kết thúc bữa ăn.", "Những tội lỗi trong quá khứ của người nói điều đó sẽ được tha thứ."),
        "dua_host" to DuaText("Dành cho chủ nhà", "Lạy Allah, xin ban phúc lành cho họ với những gì Ngài đã ban cho họ, tha thứ cho họ và thương xót họ.", "Đối với chủ nhà, sau khi dùng bữa tại nhà người khác.", "Cảm ơn chủ nhà theo cách Sunnah."),
        "dua_breaking_fast" to DuaText("Sau khi nhịn ăn", "Cơn khát đã qua đi, huyết mạch được làm ẩm và phần thưởng sẽ được xác nhận nếu Allah muốn.", "Vào thời điểm iftar.", "Nhà tiên tri ﷺ đã nói điều này khi ăn chay."),
        "dua_new_clothes" to DuaText("Mặc quần áo mới", "Ôi Allah, mọi lời khen ngợi đều thuộc về Ngài; Bạn đã mặc cho tôi cái này. Tôi cầu xin Ngài những điều tốt lành và tốt đẹp cho những gì nó được tạo ra, đồng thời tôi cầu xin Ngài che chở khỏi những điều xấu xa và xấu xa của những gì nó được tạo ra.", "Khi mặc một bộ quần áo mới (đặt tên cho nó, chẳng hạn như áo sơ mi hoặc khăn xếp).", "Nhà tiên tri ﷺ đã thực hiện điều này khi mặc một bộ quần áo mới. (Thời gian mặc quần áo hàng ngày nằm trong phần 'Mặc quần áo'.)"),
        "dua_rabbana_atina" to DuaText("Điều tốt ở đời này và đời sau", "Lạy Chúa, xin ban cho chúng con điều tốt lành ở đời này và điều tốt lành ở Đời sau, và bảo vệ chúng con khỏi sự trừng phạt của Lửa.", "Việc dua the Prophet ﷺ được thực hiện thường xuyên nhất.", "Một dua tập hợp mọi điều tốt đẹp của thế giới này và Đời sau."),
        "dua_rabbi_zidni_ilma" to DuaText("Tăng cường kiến thức", "Lạy Chúa, xin gia tăng kiến ​​thức cho con.", "Để nâng cao kiến ​​thức.", "Allah đã ra lệnh cho Nhà tiên tri ﷺ không yêu cầu tăng thêm gì ngoài kiến ​​thức."),
        "dua_musa_sharh_sadr" to DuaText("Mở Rương (Musa AS)", "Lạy Chúa, xin hãy mở rộng lồng ngực cho con, giảm bớt nhiệm vụ cho con và tháo nút thắt trên lưỡi con để họ có thể hiểu được lời nói của con.", "Trước một kỳ thi, một bài phát biểu hoặc bất kỳ nhiệm vụ khó khăn nào.", "Dua của Nhà tiên tri Musa (AS) — tâm hồn bình tĩnh và thoải mái trong công việc."),
        "dua_la_tuzigh" to DuaText("Sự kiên định của trái tim", "Lạy Chúa, xin đừng để lòng chúng con chệch hướng sau khi Chúa hướng dẫn chúng con và xin ban cho chúng con lòng thương xót của Chúa. Quả thực, Ngài là Đấng Ban Phước.", "Vì sự kiên định khi được hướng dẫn.", "Một dua cho việc giữ vững niềm tin."),
        "dua_ya_muqallib" to DuaText("Hỡi người xoay trái tim", "Hỡi người xoay chuyển trái tim, xin hãy giữ cho trái tim tôi vững chắc với tôn giáo của Ngài.", "Nhà tiên tri ﷺ thường làm điều này.", "Theo Umm Salamah (RA), lời tiên tri ﷺ được thực hiện thường xuyên nhất."),
        "dua_la_tuakhidhna" to DuaText("Những câu thơ cuối cùng của Surah Al-Baqarah", "Lạy Chúa, xin đừng bắt chúng con phải làm việc nếu chúng con quên hoặc phạm sai lầm. Lạy Chúa, xin đừng đặt lên chúng con gánh nặng giống như gánh nặng mà Chúa đã đặt lên những người trước chúng con. Lạy Chúa, xin đừng tạo gánh nặng cho chúng con với những gì chúng con không thể gánh nổi. Xin tha thứ cho chúng tôi, tha thứ cho chúng tôi và thương xót chúng tôi. Bạn là Người bảo vệ của chúng tôi, vì vậy hãy giúp chúng tôi chống lại những người không tin tưởng.", "Vào ban đêm trước khi ngủ - hai câu thơ cuối cùng của Surah al-Baqarah.", "Bất cứ ai đọc hai câu cuối cùng của Surah al-Baqarah vào ban đêm, họ sẽ đủ cho anh ta."),
        "dua_visiting_sick" to DuaText("Thăm người bệnh", "Tôi cầu xin Allah Đấng Toàn năng, Chúa tể của ngai vàng quyền năng, chữa lành cho bạn.", "Bảy lần khi đến thăm người bệnh.", "Nếu thời điểm chết chưa đến, Allah sẽ chữa lành cho anh ta."),
        "dua_ruqyah_pain" to DuaText("Cho nỗi đau thể xác", "Tôi cầu xin sự che chở nơi Allah và quyền năng của Ngài khỏi sự xấu xa của những gì tôi cảm thấy và những gì tôi sợ hãi.", "Đặt bàn tay của bạn vào nơi bị đau, nói Bismillah ba lần, sau đó nói dua bảy lần.", "Nhà tiên tri ﷺ đã dạy điều đó cho Uthman ibn Abil-'As (RA) về nỗi đau."),
        "dua_ruqyah_nabawi" to DuaText("Ruqyah tiên tri cho người bệnh", "Ôi Allah, Chúa của nhân loại! Hãy loại bỏ tác hại và ban cho sự chữa lành, vì Bạn là Đấng chữa lành; không có phương pháp chữa trị nào ngoại trừ phương pháp chữa trị của Ngài - một phương pháp chữa trị không để lại bệnh tật nào.", "Khi đưa tay cho người bệnh.", "Nhà tiên tri ﷺ đã kể lại điều này khi đến thăm những người thân trong gia đình bị bệnh."),
        "dua_kalimat_tammat" to DuaText("Tìm nơi nương tựa bằng những lời nói hoàn hảo", "Tôi tìm nơi ẩn náu trong những lời nói hoàn hảo của Allah để tránh khỏi sự xấu xa của những gì Ngài đã tạo ra.", "Khi dừng lại ở một nơi nào đó, hoặc vào buổi tối.", "Ai dừng lại ở một nơi và nói điều này, sẽ không có gì làm hại người đó cho đến khi người đó rời khỏi nơi đó."),
        "dua_evil_eye" to DuaText("Bảo vệ trẻ em (Mắt quỷ)", "Tôi tìm kiếm sự bảo vệ cho cả hai bạn bằng những lời nói hoàn hảo của Allah khỏi mọi ma quỷ và mọi sinh vật độc hại, cũng như khỏi mọi con mắt có hại.", "Nhà tiên tri ﷺ đã đọc điều này trên Hasan và Husain (RA).", "Một Sunnah dua để bảo vệ trẻ em khỏi con mắt độc ác và bị tổn hại (một đứa trẻ sẽ nói 'U'īdhuka')."),
        "dua_seeing_afflicted" to DuaText("Nhìn thấy ai đó đang bị xét xử", "Mọi lời khen ngợi đều dành cho Allah, Đấng đã tha thứ cho tôi khỏi những gì Ngài đã thử thách bạn và đã ưu ái tôi hơn phần lớn sự sáng tạo của Ngài.", "Khi nhìn thấy ai đó trong phiên tòa (hãy nói thầm với chính mình).", "Người nói ra điều đó sẽ được an toàn khỏi cuộc thử thách đó."),
        "dua_istikhara" to DuaText("Salat al-Istikhara", "Ôi Allah, tôi tìm kiếm điều tốt nhờ kiến ​​thức của Ngài, tôi tìm kiếm khả năng nhờ sức mạnh của Ngài và tôi cầu xin Ngài về hồng ân vĩ đại của Ngài. Bạn có quyền lực còn tôi thì không; Bạn biết còn tôi thì không, và Bạn là Người biết những điều vô hình. Ôi Allah, nếu theo sự hiểu biết của Ngài, vấn đề này (hãy ghi nhớ nó) là tốt cho tôn giáo, cuộc sống và mục đích của tôi, thì hãy ra lệnh cho tôi, tạo điều kiện dễ dàng cho tôi và ban phước cho tôi trong đó. Và nếu theo sự hiểu biết của Ngài, vấn đề này có hại cho tôn giáo, cuộc sống và mục đích của tôi, thì hãy tránh xa nó và khiến tôi tránh xa nó, và ra lệnh cho tôi điều tốt dù nó ở đâu, thì hãy làm cho tôi bằng lòng với nó.", "Sau hai lần rak'ah tự nguyện cầu nguyện, hãy tìm kiếm điều tốt nhất trong một vấn đề được phép.", "Nhà tiên tri ﷺ đã dạy istikhara những người bạn đồng hành trong mọi vấn đề khi ông dạy họ một surah của Kinh Qur'an."),
    )
}
